const cast = [
 {id:'giggle',name:'Leo',look:'Existing DLL Studio orange Spinosaurus superhero. Long orange snout, teal eyes, cream jaw, spectacular blue sail with orange ribs, blue armored suit with orange trim, silver wrist guards, lightning chest emblem, tool belt and clawed feet. Use public/characters/leo.png as the authoritative identity reference. Captain Giggle is his adventure role; never replace him with a human.',scale:'1.0 unit',voice:'Warm mid-range voice, buoyant and sincere; let terrible jokes land in a small silence.',trait:'Brave, optimistic, clumsy and kind. Laughter is an invitation, never mind control; he listens before joking about a sad feeling.'},
 {id:'zip',name:'Zip',look:'Small russet squirrel; cream muzzle, single large curled tail; orange goggles with clear lenses and brown tool belt. Always four limbs, two ears, one tail.',scale:'0.45 unit',voice:'Quick, crisp and logical, but slow down for instructions.',trait:'Inventive, energetic; owns mistakes. Gadgets work through visibly impossible cartoon mechanisms, not reproducible construction instructions.'},
 {id:'luna',name:'Luna',look:'Young human inventor; medium-brown skin, dark wavy bob; purple jacket, teal backpack, glowing star-shaped badge, teal trousers and white shoes.',scale:'0.8 unit',voice:'Calm, clear, curious. A short pause before observations.',trait:'Observant and creative. Her soft holograms guide and illuminate; never point beams into eyes.'},
 {id:'boomer',name:'Boomer',look:'Oversized rounded robot dog; cream shell, teal ear panels and paws, blue oval eyes on a charcoal face screen, yellow chest light. Four short legs; no sharp hardware.',scale:'0.75 unit at shoulder',voice:'Friendly rounded voice with occasional gentle electronic chirps; dialogue always understandable.',trait:'Loyal and snack-distracted. Protective bubbles are obvious fantasy and remain near ground level.'},
 {id:'snapper',name:'Snapper',look:'Giant mint-green cartoon crocodile; pale lime belly, broad rounded muzzle, large gentle amber eyes, small rounded white teeth, four short legs, one broad flexible tail; oversized bright yellow floppy hat with teal band.',scale:'2.2 units high; 3.5 long',voice:'Soft low voice; hesitant at first, warmer later. Never a roar.',trait:'Lonely and misunderstood. Wants connection, apologizes for taking the cake and helps repair the harm. Kindness does not excuse taking things.'}
];
