// Preserve the established DLL Studio lead in every production segment.
function adaptLeo(value){
 if(typeof value==='string')return value.replaceAll('Captain Giggle','Leo').replaceAll('Giggle','Leo').replace(/\bcape\b/g,'parade ribbon').replace(/\bhair\b/g,'sail');
 if(Array.isArray(value))return value.map(adaptLeo);
 if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,adaptLeo(v)]));
 return value;
}
for(let i=0;i<scenes.length;i++){scenes[i]=adaptLeo(scenes[i]);if(!scenes[i].characters.includes('giggle'))scenes[i].characters.unshift('giggle');}
// The brief specifically requests eight seconds for the first choice and key puzzle.
// Their ten-second beats include two seconds of card preview, then eight seconds to answer.
for (const index of [3,16]) {
 scenes[index].interaction.at=12;
 scenes[index].interaction.duration=8;
 scenes[index].beats[1].action='Preview the three cards for two seconds, then hold the choice image steady for eight full response seconds. No dialogue or urgency sounds.';
}
scenes[17].beats[5].dialogue=[{speaker:'Narrator',text:'You may clap softly twice and wave, or imagine it, or just listen. Join in your own way.'}];
const palettes=['Sky blue, sunflower yellow, coral and fresh mint; soft sunny daylight','Apricot, teal, butter yellow; broad diffuse daylight','Mint green, sky blue and warm yellow; no ominous shadows'];
for(const s of scenes){
 s.camera=s.interaction ? 'Establish in a wide shot; eye-level medium character coverage. Lock camera throughout each puzzle/choice hold. Use an unhurried push-in for the resolution; no whip pans.' : 'Establish geography in a wide shot, then eye-level two-shots and readable reaction close-ups. Keep screen direction consistent; use one gentle tracking move.';
 s.motion='Animate the six timed beats separately in short approved shots. Preserve left/right placement and prop continuity. Use gentle squash-and-stretch, rounded poses, natural blinks, no flashing or rapid cuts. '+s.beats[2].action;
 s.lighting=palettes[(s.id-1)%3];
 s.music=s.id===19 ? 'Original “Everyone Belongs”: 96 BPM, 4/4, C major, 24 bars / 60 seconds; bars 1–4 instrumental movement window, 5–16 verses/chorus, 17–20 response window, 21–24 final refrain. Original melody only; soft piano, mallets, bass and brushed percussion. No artist imitation.' : s.id===11||s.id===12 ? 'Original sparse warm piano and soft strings at 72 BPM; leave clear space for dialogue. No sad shock cue.' : 'Original playful marimba, pizzicato strings and brushed percussion at 96 BPM; duck beneath dialogue; use quiet curiosity cadence at scene end.';
 s.visualPrompt=`High-quality colorful 3D children’s animation, ${s.characters.map(id=>cast.find(c=>c.id===id).name).join(', ')} in ${s.location}, performing ${s.beats[0].action} Expressive faces, playful physical comedy, cinematic but child-friendly composition, bright soft lighting, polished animated-film look, consistent character design, clean background, 16:9 widescreen. ${s.lighting}. Use approved character reference sheets and the exact model/wardrobe locks below. This is a single establishing keyframe, not a request to compress a minute into one generation. Composite all lettering afterward.`;
 s.consistency=s.characters.map(id=>cast.find(c=>c.id===id));
 s.negativePrompt=negative;
 s.shotPrompts=s.beats.map((b,i)=>({id:`S${String(s.id).padStart(2,'0')}-${i+1}`,start:b.start,duration:b.duration,prompt:`High-quality colorful 3D children’s animation, ${s.characters.map(id=>cast.find(c=>c.id===id).name).join(', ')} in ${s.location}, performing ${b.action} Expressive faces, playful physical comedy, cinematic but child-friendly composition, bright soft lighting, polished animated-film look, consistent character design, clean background, 16:9 widescreen. ${s.camera} ${s.lighting}. Keep approved reference identities and scale. No generated lettering; composite text and captions in editing.`,negativePrompt:negative}));
}
const project={title,version:1,ageRange:'6–10',duration:1200,frame:{width:1920,height:1080,aspect:'16:9',fps:24},status:'Production script and interactive storyboard; no rendered video or recorded voices included.',characters:cast,scenes};
fs.writeFileSync(path.join(out,'scenes.json'),JSON.stringify(project,null,2));
const fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const stamp=t=>`${String(Math.floor(t/3600)).padStart(2,'0')}:${fmt(t%3600)}.${String(Math.round((t%1)*1000)).padStart(3,'0')}`;
let cues=[];
for(const s of scenes) for(const b of s.beats){
 const lines=b.dialogue.length ? b.dialogue.map(d=>`${d.speaker}: ${d.text}`) : b.sfx ? [`[${b.sfx}]`] : [];
 const step=10/Math.max(1,lines.length);
 lines.forEach((line,i)=>cues.push(`${stamp(s.start+b.start+i*step)} --> ${stamp(s.start+b.start+(i+1)*step-.1)}\n${line}`));
}
fs.writeFileSync(path.join(out,'captions.vtt'),'WEBVTT\n\nNOTE Draft timing for animatic. Replace with recorded-dialogue timings before final release.\n\n'+cues.join('\n\n')+'\n');
const synopsis='Bubbleville’s Friendship Festival is nearly ready when a giant crocodile in a floppy yellow hat appears. Captain Giggle and his friends discover that Snapper was accidentally left off the invitation route. A mistaken cake invitation, an unreliable cupcake gadget and a windy decorating mishap send the team on a comic adventure. Viewers help choose approaches and routes, find clues and name a feeling. By listening, setting kind boundaries, returning the cake and combining their abilities, the friends turn exclusion into a welcoming parade. Snapper becomes a helper, the town apologizes for judging him, and everyone celebrates with an original song.';
let md=`# ${title}\n\nProduction kit • Ages 6–10 • 16:9 • 1920×1080 target • 24 fps • 20:00 master\n\n**Delivery status:** Complete timed production script, prompt package, original lyrics, captions draft, scene data and functioning local storyboard companion. The companion includes Leo’s existing artwork, generated supporting-character illustrations and a Bubbleville background with simple motion and pose changes. Finished scene animation, recorded voices, music and final MP4 are not included. No paid generation has been submitted. Leo, the established DLL Studio Spinosaurus, leads the entire episode as Captain Giggle. Every production segment contains Leo. Zip, Luna, Boomer and Snapper are supporting characters. Maintain Leo’s existing identity and outfit.\n\n## 1. Final title and thumbnail concept\n\n**${title}**\n\nThumbnail: a friendly Snapper in his yellow hat at right, Captain Giggle at left offering a correctly oriented invitation, and a shared cake between them. Bright sky-blue background, clear smiling eyes, three focal elements. Small optional text: “A FRIEND FOR SNAPPER”. No threatening teeth, frightened faces, claim of danger, or misleading monster pose. Render art without text, then add accessible lettering. Original designs are proposed; name/design clearance is a release task, not a claim made by this kit.\n\n## 2. Synopsis\n\n${synopsis}\n\n## 3. Character bible\n\nStyle lock: rounded, polished 3D cartoon characters with soft materials and diffuse lighting. Bubbleville has pastel round houses, broad flat paths and a fenced pond garden. Maintain one sun direction per sequence. Create approved front/side/three-quarter turnarounds, six expressions and relative scale sheet before any video generation. Use these same reference assets for every shot; prompt repetition alone cannot guarantee consistency.\n\n`;
for(const c of cast) md+=`### ${c.name}\n\n- Design: ${c.look}\n- Relative scale: ${c.scale}.\n- Performance: ${c.trait}\n- Voice: ${c.voice}\n\n`;
md+='## 4. Full 20-scene script\n\nEach scene is exactly 60 seconds in the edit. Six 10-second beats specify action, all spoken words, essential sounds and overlays. Spoken lines finish within their beat; use the remaining time for acting, not faster speech. Timings are an animatic target, not a verified recording. The response windows are included in the duration. Choice scenes have a ten-second hold followed by a ten-second variant; never append a variant to the master. The linear cut uses A in scene 4, B in scene 9 and A first in scene 14. It explains “Point or say your choice; our story will try one way.” It must not claim YouTube can read an answer.\n\nBefore Scene 19, the closing narrator line in Scene 18 may be delivered over its last four seconds as: “You may clap softly twice and wave, or just listen.” This replaces, rather than adds to, its invitation line when recording.\n\n';
for(const s of scenes){
 md+=`### Scene ${s.id} — ${s.name} (${fmt(s.start)}–${fmt(s.start+60)})\n\nLocation: ${s.location}. Cast: ${s.characters.map(id=>cast.find(c=>c.id===id).name).join(', ')}.\n\n`;
 for(const b of s.beats){md+=`**${fmt(s.start+b.start)}–${fmt(s.start+b.start+10)}** — ${b.action}\n\n`;for(const d of b.dialogue)md+=`> **${d.speaker}:** ${d.text}\n\n`;md+=`Sound: ${b.sfx}.${b.onScreen?` Overlay: **${b.onScreen}**.`:''}\n\n`;}
 if(s.interaction){md+=`**Interaction:** ${s.interaction.prompt} Hold ${fmt(s.start+s.interaction.at)}–${fmt(s.start+s.interaction.at+10)} (10 seconds). ${s.interaction.type==='choice'?'Selected payoff occupies the next 10 seconds. All branches share the following beat.':'Reveal follows the hold within this scene.'}\n\n`;s.interaction.options.forEach((o,i)=>md+=`- ${'ABC'[i]} — ${o.label}. Feedback: “${o.feedback}” Variant: ${o.branch}\n`);md+='\n';}
 md+=`Next-scene hook: ${s.hook}\n\n`;
}
md+='## 5. Scene-by-scene FAL prompt package\n\nUse model-independent creative prompts below. Before rendering, an adult producer must choose a current FAL endpoint, verify its documented input fields, reference-image support, duration limits, license and price, then approve a bounded spend. Do not assume a model accepts a 60-second prompt or a negative_prompt field. Generate short shots, trim or extend in the edit, and use still holds for puzzles. Preserve the full minute in the edit, not through one model request. Scene JSON includes 120 individual beat prompts, exact timings and negative prompts. Generate branch shots A/B/C separately; their outputs replace the same timeline interval.\n\n';
for(const s of scenes){md+=`### Scene ${s.id}: ${s.name}\n\n1. **Description:** ${s.beats[0].action} Resolution: ${s.beats[5].action}\n2. **Visual-generation prompt:** ${s.visualPrompt}\n3. **Character consistency:** ${s.consistency.map(c=>`${c.name}: ${c.look} Scale ${c.scale}.`).join(' ')}\n4. **Camera:** ${s.camera}\n5. **Motion:** ${s.motion}\n6. **Lighting / palette:** ${s.lighting}.\n7. **Dialogue:** ${s.beats.flatMap(b=>b.dialogue.filter(d=>d.speaker!=='Narrator').map(d=>`${d.speaker}: “${d.text}”`)).join(' ')}\n8. **Narration:** ${s.beats.flatMap(b=>b.dialogue.filter(d=>d.speaker==='Narrator').map(d=>d.text)).join(' ')||'No narrator; characters carry this scene.'}\n9. **Sound effects:** ${s.beats.map(b=>b.sfx).join('; ')}.\n10. **Background music:** ${s.music}\n11. **On-screen text:** ${s.beats.filter(b=>b.onScreen).map(b=>b.onScreen).join(' / ')||'Dialogue captions only.'} Composite after generation.\n12. **Interaction:** ${s.interaction ? `${s.interaction.prompt} Hold for ${s.interaction.duration} seconds at scene offset ${s.interaction.at}. ${s.interaction.options.map((o,i)=>`${'ABC'[i]}: ${o.label}; ${o.branch}`).join(' ')}`:'None; continue the story.'}\n13. **Negative prompt:** ${negative}\n\n`;}
md+='## 6. Voice and sound direction\n\nRecord at 110–125 words per minute for dialogue, slower for feelings and instructions. Use consenting performers or voices licensed for this production, never celebrity imitation. The actor names in this document are roles, not real performer claims. No overlapping important speech. Narrator is warm and unhurried. Leave each answer window speech-free after the prompt. Record branch lines separately to the same duration and return pose.\n\nThe original lyrics are in Scene 19. Compose an original 96 BPM melody in C major; 24 bars of 4/4 occupy exactly 60 seconds. Bars 1–4 and 17–20 are instrumental response windows; the other 16 bars carry the lyric. Do not copy an existing tune. Final music does not exist yet. Deliver separate dialogue, music and effects stems plus clean instrumental. Duck music under speech, avoid sudden loud sounds, use moderate applause, check on headphones and small speakers, and measure final loudness/peaks for the chosen release platform. No unsupported loudness-compliance claim.\n\nDraft `captions.vtt` includes all written dialogue, lyrics and quiet sound cues. Align it to actual recordings, break lines to readable lengths, and check names/sung captions before release. The prototype shows timed script lines but does not synthesize or play voices.\n\n## 7. Interactive-choice map\n\nThe clock always has a 1,200-second story timeline. Playing shows a ten-second response window; answering early displays feedback while the remaining time runs. No answer uses the named default. Pausing stops both story and countdown. Manual replay/seek can lengthen a viewing session. Scripted responses are local-only and never imply the player heard the viewer.\n\n| Scene | Time | Activity | Result and reconnection |\n|---|---|---|---|\n| 4 | 03:10–03:20 | A ask / B cart / C dance | Variant 03:20–03:30; shared listening at 03:30; default A |\n| 7 | 06:10–06:20 | Find three stars | Reveal flag, crate, sign at 06:20; everyone sees all answers |\n| 9 | 08:10–08:20 | Three routes | Variant 08:20–08:30; pond arrival 08:30; default B |\n| 10 | 09:20–09:30 | Count cupcake bubbles | Answer 3; shared count at 09:30 |\n| 12 | 11:10–11:20 | Name Snapper’s feeling | Snapper names “lonely” at 11:20; no assumption about viewer feelings |\n| 14 | 13:10–13:20 | Choose first tool | Variant 13:20–13:30; other attempts then combined solution |\n| 17 | 16:10–16:20 | Spot key balloon | Blue oval key symbol; reveal 16:20 |\n| 19 | 18:00–18:10 | Two soft claps and wave | Optional / seated / imagined participation |\n| 19 | 18:40–18:50 | Sing or say the refrain | Ten-second instrumental response window |\n| 20 | 19:50–20:00 | Next-adventure question | Local feedback only; no submission, messaging or storage |\n\nDo not sell the linear YouTube upload as a clickable branching video. The companion supports branches through timed storyboard text; actual branch video files still require rendering and synchronization. A locally loaded final linear MP4 is a review aid, not proof that branch clips exist.\n\n## 8. Viewer-retention plan\n\nUse clear cause and effect and variety, not pressure or overstimulation. Every scene introduces a visual beat at :00, a new clue/joke or emotional turn near :30, and the listed hook at :50. Holds remain visually stable.\n\n';
md+='| Minute | Fresh development | End curiosity |\n|---|---|---|\n';for(const s of scenes)md+=`| ${s.id} | ${s.name}: ${s.beats[3].action} | ${s.hook} |\n`;
md+='\nRecurring jokes vary: Giggle’s bad puns in 1/2/7/8/13; Boomer postpones snacks in 2/6/8/11 and earns a quiet payoff in 18; Snapper’s hat shifts from awkward curtain to useful cover to invitation holder; Zip’s malfunction changes from sign to cupcakes, then becomes coordinated teamwork. Emotional disclosure in 11 and apologies in 18 remain uninterrupted.\n\n## 9. Monetization-safety checklist\n\nEditorial checklist for the written plan, not platform approval or a guarantee of revenue:\n\n- No purchases, ads, product placement, giveaways or child-directed sales prompts in this companion.\n- No login, forms, free-text chat, analytics, third-party scripts or requests for child data. Choices are in memory only.\n- No weapons, blood, threats, cruelty or realistic injury; cartoon slapstick stays floor-level and visibly impossible.\n- “Evil” occurs only as the requested mistaken label, immediately challenged and explicitly apologized for. No identity-based explanation.\n- Feelings are accepted; taking the cake is corrected. Friendship and physical affection are never demanded.\n- Balloon visuals use stylized props/racks; no popping, loose real balloons, strings or imitation instructions.\n- Original proposed designs, dialogue and lyrics; do asset provenance and name/design clearance before release.\n- Verify current YouTube audience designation, children’s content quality and monetization requirements against official policy before upload. Suitability/eligibility has not been certified here.\n\n## 10. YouTube metadata draft\n\n**Title:** Captain Giggle & the Crocodile Who Needed a Friend | 20-Min Adventure\n\n**Description:**\n\nA giant crocodile, a missing invitation, and a cake-sized misunderstanding! Join Captain Giggle, Zip, Luna and Boomer as they meet Snapper and prepare Bubbleville’s Friendship Festival. This original animated story for ages 6–10 explores asking before judging, listening to feelings, taking responsibility and working together.\n\nWatch with a grown-up. Point, count, imagine and sing along during the pauses. This video follows one story path; it cannot hear or collect your answers. You can join the movements seated, imagine them, or simply listen.\n\nFor grown-ups: After watching, ask “What helped Snapper make things right?” and “How could we help someone feel welcome?”\n\nProduction credit: DLL Studio. Add verified performer, music and asset credits only after production and rights review. Do not publish this draft as if the finished film already exists.\n\n**Tags:** Captain Giggle, Snapper crocodile, original kids animation, friendship story, teamwork, family adventure, kids comedy, kindness, listening, ages 6 to 10, sing along, Bubbleville\n\n**Chapters:**\n\n';
for(const s of scenes)md+=`${fmt(s.start)} ${s.name}\n\n`;
md+='## 11. HTML, CSS and JavaScript companion\n\nOpen `index.html` through the local web server. Implementation files: `index.html`, `style.css`, `app.js`, `timeline.mjs`, `scenes.json`, `captions.vtt`. Includes native local-video review, separate pause/play and seek controls, a progress bar, ten-to-zero timer, A/B/C choices, keyboard-operable object targets, optional restrained celebration, friendly feedback, mute, captions, replay interaction, chapter navigation and reduced-motion styling. No dependencies, external fonts, network API calls, trackers or child accounts. The scene-data and captions fetches are same-origin static assets. Local video uses an object URL and is never uploaded.\n\nThe default is explicitly a silent timed storyboard. Captions show the script; they are not a recording. A loaded video is used as the master clock and gets the draft caption track. If its length is not 20 minutes, a visible warning explains the mismatch. This prototype does not splice rendered branch footage.\n\n## 12. Server-side API pseudocode\n\nSee `server-pseudocode.md` and `.env.example` in the production documentation directory, outside the public companion. No generation endpoint is deployed. API requests belong in an authenticated adult production tool, never on a child-facing route. Placeholders only: FAL_KEY=YOUR_FAL_API_KEY and OPENAI_API_KEY=YOUR_OPENAI_API_KEY.\n\n## 13. JSON scene schema\n\n`scene-schema.json` defines the delivered `scenes.json`: twenty scenes, 60 seconds each, six 10-second beats, cast IDs, generation prompts, typed interactions and three-way options. Cross-field tests additionally verify total duration, sequential starts, pause placement, branch reconnection and scene count; JSON Schema alone does not enforce all arithmetic.\n\n## 14. Quality-control checklist\n\n**Checked in this delivery:** twenty scenes and 1,200 seconds; 120 timed beats; three branching decisions; two object games; counting, feelings, movement, sing-along and final question; ten-second response holds; complete script and per-scene thirteen-field prompt package; draft captions; frontend contains no keys or generation calls. See validation output for executable checks.\n\n**Required before calling it a finished film:**\n\n- Approve all five reference sheets and test identity/scale/wardrobe consistency in actual renders.\n- Assemble and watch a 20-minute animatic; time spoken lines and song; adjust within beat windows.\n- Render and inspect every frame for distorted bodies, frightening expressions, accidental symbols or text, unsafe-looking movement and continuity.\n- Record/mix voices and music; verify rights, consent, intelligibility, loudness and no sudden peaks.\n- Align captions to final audio, include important sounds and lyrics, and verify contrast/safe areas at 1920×1080 and on a phone.\n- Test every actual branch clip, default/no answer, late click, replay, pause/resume, seeking and video-end behavior.\n- Review with parents/educators and children accompanied by their adults; collect adult feedback without collecting child identifiers.\n- Verify current platform requirements and accurate audience designation; never guarantee monetization or YouTube Kids inclusion.\n- Export H.264 MP4 or platform-appropriate delivery from the verified 16:9 master; inspect the exported file, not just the editor timeline.\n\nNo finished video, audio, rights clearance or platform approval is implied by passing the code and script checks.\n';
md=md.replace('Each scene is exactly 60 seconds in the edit.','Each scene is exactly 60 seconds in the edit. Scenes 4 and 17 use the requested eight-second answer windows, preceded by two seconds of visual preview; other response windows are ten seconds.');
